CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TYPE "Role" AS ENUM ('SUPER_ADMIN','AGENCY_ADMIN','CLIENT_ADMIN','OPERATOR');
CREATE TYPE "PlanType" AS ENUM ('TRIAL','STARTER','PRO','ENTERPRISE');
CREATE TABLE "tenants" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"document" TEXT,"plan" "PlanType" NOT NULL DEFAULT 'STARTER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "tenants_pkey" PRIMARY KEY ("id"));
CREATE TABLE "users" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'OPERATOR',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "users_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "users_email_key" ON "users"("email"); CREATE INDEX "users_tenantId_idx" ON "users"("tenantId");
CREATE TABLE "agents" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"name" TEXT NOT NULL,"niche" TEXT NOT NULL,"provider" TEXT NOT NULL DEFAULT 'openai',"model" TEXT NOT NULL DEFAULT 'gpt-4o',"temperature" DOUBLE PRECISION NOT NULL DEFAULT 0.4,"roleText" TEXT NOT NULL,"taskText" TEXT NOT NULL,"contextText" TEXT NOT NULL,"executionText" TEXT NOT NULL,"variablesJson" JSONB NOT NULL DEFAULT '{}',"fullSystemPrompt" TEXT NOT NULL,"instanceName" TEXT,"whatsappStatus" TEXT NOT NULL DEFAULT 'DISCONNECTED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "agents_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "agents_instanceName_key" ON "agents"("instanceName"); CREATE INDEX "agents_tenantId_idx" ON "agents"("tenantId");
CREATE TABLE "knowledge_files" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"agentId" TEXT NOT NULL,"fileName" TEXT NOT NULL,"fileSize" INTEGER NOT NULL,"mimeType" TEXT NOT NULL,"chunksCount" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "knowledge_files_pkey" PRIMARY KEY ("id"));
CREATE INDEX "knowledge_files_tenantId_agentId_idx" ON "knowledge_files"("tenantId","agentId");
CREATE TABLE "rooms" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"title" TEXT NOT NULL,"topic" TEXT NOT NULL,"targetAudience" TEXT,"objective" TEXT,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "rooms_pkey" PRIMARY KEY ("id"));
CREATE INDEX "rooms_tenantId_idx" ON "rooms"("tenantId");
CREATE TABLE "room_messages" ("id" TEXT NOT NULL,"roomId" TEXT NOT NULL,"senderType" TEXT NOT NULL,"agentRole" TEXT NOT NULL,"senderName" TEXT NOT NULL,"content" TEXT NOT NULL,"imageUrl" TEXT,"metadata" JSONB NOT NULL DEFAULT '{}',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "room_messages_pkey" PRIMARY KEY ("id"));
CREATE INDEX "room_messages_roomId_idx" ON "room_messages"("roomId");
ALTER TABLE "users" ADD CONSTRAINT "users_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "agents" ADD CONSTRAINT "agents_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "knowledge_files" ADD CONSTRAINT "knowledge_files_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "knowledge_files" ADD CONSTRAINT "knowledge_files_agentId_fkey" FOREIGN KEY ("agentId") REFERENCES "agents"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "rooms" ADD CONSTRAINT "rooms_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "room_messages" ADD CONSTRAINT "room_messages_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "rooms"("id") ON DELETE CASCADE ON UPDATE CASCADE;